    <?= view('templates/_breadcrumb', ['module' => 'admin', 'menu_title' => 'Administration', 'page' => 'Roles']) ?>
    <div class="access-hero"><div><div class="access-eyebrow">Administration · Identity & Access</div><h4>Roles</h4><p class="access-muted mb-0">Define reusable access profiles and assign permissions in one focused workflow.</p></div><button class="btn btn-primary" type="button" id="new-role"><i class="fa fa-plus mr-1"></i> New role</button></div>
    <nav class="access-nav" aria-label="Identity and access navigation"><a href="<?= base_url('admin/access/users') ?>">Users</a><a class="active" href="<?= base_url('admin/access/roles') ?>">Roles</a><a href="<?= base_url('admin/access/permissions') ?>">Permissions</a></nav><div id="access-alert" role="status" aria-live="polite"></div>
    <div class="row"><div class="col-lg-5 mb-4"><div class="access-card"><div class="card-header"><div class="access-toolbar"><input class="form-control" id="role-search" type="search" placeholder="Search roles" aria-label="Search roles"><select class="form-control" id="role-status" aria-label="Filter roles"><option value="">All statuses</option><option value="1">Active</option><option value="0">Disabled</option></select></div></div><div class="list-group list-group-flush" id="role-list"><?php foreach ($roles as $role): ?><?php $assigned = array_map('intval', array_column(array_filter($rolePermissions, static fn ($row) => (int) $row['role_id'] === (int) $role['id']), 'permission_id')); $roleLabel = display_role_label($role['role_name'] ?? '', $role['role_code'] ?? ''); ?><button type="button" class="list-group-item list-group-item-action role-row" data-id="<?= (int) $role['id'] ?>" data-name="<?= esc(strtolower($roleLabel . ' ' . $role['role_code']), 'attr') ?>" data-status="<?= (int) $role['status'] ?>" data-role='<?= esc(json_encode($role), 'attr') ?>' data-permissions='<?= esc(json_encode($assigned), 'attr') ?>'><div class="d-flex justify-content-between"><strong><?= esc($roleLabel) ?></strong><span class="access-badge <?= (int) $role['status'] === 1 ? 'active' : 'disabled' ?>"><?= (int) $role['status'] === 1 ? 'Active' : 'Disabled' ?></span></div><small class="access-muted"><?= esc($role['role_code']) ?> · <?= count($assigned) ?> permissions<?= (int) $role['is_system'] ? ' · System role' : '' ?></small></button><?php endforeach; ?><?php if ($roles === []): ?><div class="access-empty">No roles found.</div><?php endif; ?></div></div></div>
    <div class="col-lg-7 mb-4"><div class="access-card"><div class="card-header"><h5 class="mb-0" id="role-editor-title">Create role</h5><small class="access-muted">System roles are protected. Permission changes replace the selected role’s assignments transactionally.</small></div><div class="card-body"><form id="role-form" class="access-form"><input type="hidden" name="id"><?= csrf_field() ?><div class="form-row"><div class="form-group col-md-6"><label for="role_name">Role name</label><input class="form-control" id="role_name" name="role_name" required><div class="validation-error" id="role_nameErr"></div></div><div class="form-group col-md-6"><label for="role_code">Role code</label><input class="form-control" id="role_code" name="role_code" required><div class="validation-error" id="role_codeErr"></div></div><div class="form-group col-12"><label for="role_description">Description</label><textarea class="form-control" id="role_description" name="description" rows="2"></textarea><div class="validation-error" id="descriptionErr"></div></div><div class="form-group col-12"><label><input type="checkbox" name="status" value="1" checked> Active</label><div class="validation-error" id="statusErr"></div></div></div><button class="btn btn-primary save-role" type="submit">Save role</button> <button class="btn btn-light reset-role" type="button">Clear</button></form><hr><div class="d-flex justify-content-between align-items-center mb-2"><label class="mb-0" for="permission-search">Permissions <span class="access-count" id="permission-count">0 selected</span></label><div><button type="button" class="btn btn-sm btn-link select-all">Select all</button><button type="button" class="btn btn-sm btn-link clear-all">Clear all</button></div></div><input class="form-control mb-2" id="permission-search" type="search" placeholder="Search permissions" aria-label="Search permissions"><div class="validation-error" id="permission-searchErr"></div><div class="permission-groups" id="permission-groups"><?php $group = '';

foreach ($permissions as $permission): ?><?php if ($group !== $permission['module']): ?><?php if ($group !== ''): ?></div><?php endif; ?><?php $group = $permission['module']; ?><div class="permission-group" data-module="<?= esc(strtolower($group), 'attr') ?>"><div class="permission-group-title"><?= esc($group) ?></div><?php endif; ?><label class="permission-option" data-search="<?= esc(strtolower($permission['permission_key'] . ' ' . $permission['permission_name']), 'attr') ?>"><input type="checkbox" class="permission-check" value="<?= (int) $permission['id'] ?>"><span><?= esc($permission['permission_name']) ?><small class="d-block"><?= esc($permission['permission_key']) ?></small></span></label><?php endforeach; ?><?php if ($group !== ''): ?></div><?php endif; ?></div><button type="button" class="btn btn-outline-primary mt-3 assign-permissions">Save permission assignments</button></div></div></div></div>
</main>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><script>
$(function(){const roleForm=$('#role-form');const alertBox=$('#access-alert');let selectedRole=0;function notify(ok,msg){alertBox.html('<div class="alert '+(ok?'alert-success':'alert-danger')+' alert-dismissible fade show" role="alert">'+$('<div>').text(msg).html()+'<button type="button" class="close" data-dismiss="alert" aria-label="Close"><span aria-hidden="true">&times;</span></button></div>');}function post(url,data){ajaxRequest({url:url,data:data,success:function(r){if(r.status){notify(true,r.msg);setTimeout(function(){location.reload();},650);}else{notify(false,r.msg);}}});}function setPermissions(ids){$('.permission-check').prop('checked',false);ids.forEach(function(id){$('.permission-check[value="'+id+'"]').prop('checked',true);});$('#permission-count').text(ids.length+' selected');}function reset(){selectedRole=0;roleForm[0].reset();roleForm.find('[name=id]').val('');$('#role-editor-title').text('Create role');setPermissions([]);}$('.role-row').on('click',function(){const row=$(this);const role=JSON.parse(row.attr('data-role'));selectedRole=role.id;roleForm.find('[name=id]').val(role.id);roleForm.find('[name=role_name]').val(role.role_name);roleForm.find('[name=role_code]').val(role.role_code);roleForm.find('[name=description]').val(role.description||'');roleForm.find('[name=status]').prop('checked',String(role.status)==='1');$('#role-editor-title').text('Edit '+role.role_name);setPermissions(JSON.parse(row.attr('data-permissions')||'[]'));});$('#new-role,.reset-role').on('click',reset);roleForm.on('submit',function(e){e.preventDefault();post('<?= base_url('admin/access/roles/save') ?>',roleForm.serialize());});$('.assign-permissions').on('click',function(){if(!selectedRole){notify(false,'Select a role first.');return;}const data=$('#role-form').serializeArray();$('.permission-check:checked').each(function(){data.push({name:'permission_ids[]',value:this.value});});post('<?= base_url('admin/access/roles') ?>/'+selectedRole+'/permissions',data);});$('.select-all').on('click',function(){$('.permission-option:visible .permission-check').prop('checked',true).trigger('change');});$('.clear-all').on('click',function(){$('.permission-check').prop('checked',false).trigger('change');});$('.permission-check').on('change',function(){$('#permission-count').text($('.permission-check:checked').length+' selected');});$('#permission-search').on('input',function(){const q=$(this).val().toLowerCase();$('.permission-option').each(function(){$(this).toggle(!q||$(this).data('search').indexOf(q)!==-1);});$('.permission-group').each(function(){$(this).toggle($(this).find('.permission-option:visible').length>0);});});$('#role-search,#role-status').on('input change',function(){const q=$('#role-search').val().toLowerCase();const s=$('#role-status').val();$('.role-row').each(function(){const row=$(this);row.toggle((!q||row.data('name').indexOf(q)!==-1)&&(!s||String(row.data('status'))===s));});});reset();});
</script><?= $this->endSection() ?>
